@app.cell(hide_code=True)
def siapkan():
    import pathlib
    import sys

    import marimo as mo

    PKG_DIR = pathlib.Path.home() / ".meja_redaksi" / "pkg" / "1ec86f1d78d5"

    def tulis(rel, src):
        """Tulis satu file paket dari teks di sel.

        Baris terakhir string adalah indentasi sebelum kutip penutup. Indentasi selebar itu dibuang dari tiap baris,
        jadi hasilnya sama persis baik marimo sudah meratakan badan sel maupun belum.
        """
        lines = src.split("\n")
        pad = len(lines[-1])
        text = "\n".join(ln[pad:] if ln[:pad].strip() == "" else ln for ln in lines[1:-1])
        path = PKG_DIR / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text("utf-8") != text:
            path.write_text(text, "utf-8")
        return rel

    return PKG_DIR, mo, sys, tulis


