@app.cell(hide_code=True)
def meja_archive_py(tulis):
    # meja/archive.py
    f_meja_archive_py = tulis("meja/archive.py", r'''
    """Arsip JSON: simpan dan muat seluruh berkas (naskah, fakta, varian, pilihan, riwayat, audit)."""
    from __future__ import annotations

    import json

    SCHEMA = "meja-redaksi/arsip@1"
    FIELDS = ("title", "profile", "raw", "clean", "italic", "facts", "ignored", "locks", "settings", "variants", "picks",
              "final_source", "final_text", "history", "hpos", "notes", "proof", "rapat", "segel", "audit", "stamp", "ck",
              "telaah", "saran", "auto", "roles", "kode", "terjemahan", "policy_ok", "impor", "fork_of", "lampiran")
    MEJA_SCHEMA = "meja-redaksi/meja@1"
    MEJA_EXTRA = ("layer_a", "rules_proposal", "compare")


    def dump(b, app: dict, kamus: list[str]) -> dict:
        data = {"schema": SCHEMA, "app": {"name": app["name"], "version": app["version"]}, "saved": None, "kamus": kamus}
        bd = {}
        for f in FIELDS:
            v = getattr(b, f)
            if isinstance(v, set):
                v = sorted(v)
            if f == "lampiran":
                v = [{k: x[k] for k in x if k != "data"} for x in v]  # isi lampiran tidak masuk arsip JSON
            bd[f] = v
        data["berkas"] = bd
        return data


    def dumps(b, app: dict, kamus: list[str], saved_iso: str) -> bytes:
        d = dump(b, app, kamus)
        d["saved"] = saved_iso
        return json.dumps(d, ensure_ascii=False, indent=1, default=str).encode("utf-8")


    def load(raw: bytes) -> dict:
        try:
            d = json.loads(raw.decode("utf-8"))
        except Exception as ex:
            raise ValueError(f"File arsip tidak bisa dibaca: {ex}")
        if d.get("schema") != SCHEMA or "berkas" not in d:
            # arsip notebook Kaggle lama: {"meta":..., "variants":[...]}
            if "variants" in d and isinstance(d["variants"], list):
                vs = d["variants"]
                asli = next((v for v in vs if v.get("name") == "ASLI"), vs[0] if vs else None)
                if not asli:
                    raise ValueError("Arsip tidak berisi varian.")
                return {"legacy": True, "text": asli["text"], "variants": vs}
            raise ValueError("Ini bukan arsip MEJA REDAKSI (hasil_*.json).")
        return d


    def dump_meja(kantor, saved_iso: str) -> bytes:
        """Seluruh meja (semua berkas) untuk dipulihkan kalau sesi/kernel mati. Disimpan di MEJA_HOME, bukan di repo."""
        out = []
        for bid in kantor.order:
            b = kantor.berkas[bid]
            bd = dump(b, kantor.app, [])["berkas"]
            for f in MEJA_EXTRA:
                bd[f] = getattr(b, f)
            bd["_id"] = b.id
            out.append(bd)
        d = {"schema": MEJA_SCHEMA, "app": {"name": kantor.app["name"], "version": kantor.app["version"]}, "saved": saved_iso,
             "order": list(kantor.order), "active": kantor.active, "running": bool(kantor.running), "berkas": out}
        return json.dumps(d, ensure_ascii=False, default=str).encode("utf-8")


    def load_meja(raw: bytes) -> dict:
        d = json.loads(raw.decode("utf-8"))
        if d.get("schema") != MEJA_SCHEMA or not isinstance(d.get("berkas"), list):
            raise ValueError("bukan file meja MEJA REDAKSI")
        return d

    ''')
    return (f_meja_archive_py,)


