        ("holistik", r"(?:secara\s+)?holistik", "kosakata", 3, "kosakata AI", "Sebut bagian apa saja yang dicakup."),
        ("sinergi", r"(?:ber|me)?sinergi(?:s|kan|nya)?|menyinergikan|disinergikan", "kosakata", 3, "kosakata AI",
         "Sebut siapa bekerja dengan siapa, mengerjakan apa."),
        ("komprehensif", r"(?:secara\s+)?komprehensif", "kosakata", 2, "kosakata AI", "Sebut apa saja yang dicakup."),
        ("esensial", r"esensial", "kosakata", 2, "kosakata AI", "Pakai \"penting\", atau jelaskan kenapa tak bisa ditinggal."),
        ("transformatif", r"transformatif", "kosakata", 3, "kosakata AI", "Sebut apa yang berubah, dari apa ke apa."),
        ("revolusioner", r"revolusioner", "kosakata", 2, "kosakata AI", "Sebut bedanya dengan yang lama, secara konkret."),
        ("inovatif", r"inovatif", "kosakata", 1, "kosakata AI", "Sebut apa yang baru."),
