@app.cell(hide_code=True)
def meja_stations_humas_py(tulis):
    # meja/stations/humas.py
    f_meja_stations_humas_py = tulis("meja/stations/humas.py", r'''
    """Bagian Humas: humanizer (atau model LLM lain) per bait/kalimat, dengan penolakan bila fakta rusak.

    Setiap deret satuan yang tidak terkunci dalam satu blok dikirim ke model. Keluaran ditolak kalau
    jumlah satuannya berubah, ada fakta hilang, ada angka/nama baru, atau ada dash/non-ASCII yang dilarang
    profil. Ditolak N kali → satuan aslinya yang dipakai.

    Satpam (kalau nyala, mode "saring"): keluaran yang lolos cek fakta dinilai poin slop-nya. Yang bersih langsung
    diterima. Kalau belum ada yang bersih, percobaan dilanjutkan sampai jatah habis, lalu dipilih yang paling bersih
    asal tidak lebih slop dari teks masukannya. Kalau semua lebih slop, satuan aslinya yang dipakai.
    Mode "catat": keluaran pertama yang lolos cek fakta diterima, nilai Satpam cuma dicatat di log.
    """
    from __future__ import annotations

    from .. import facts as F
    from .. import satpam as SP
    from .. import units as U
    from ..hub import OFFICIAL_GEN
    from ..textcheck import run_problems
    from .base import Ctx, Station

    MAX_RUN = {"line": 12, "sentence": 4, "paragraph": 1}


    class Humas(Station):
        id = "humas"
        label = "Bagian Humas · humanizer"
        office = "Bagian Humas"
        model = True
        blockwise = True

        def plan(self, units, ctx: Ctx):
            runs, cur, cur_block = [], [], None
            cap = MAX_RUN.get(ctx.profile["unit"], 4)
            for i, t in enumerate(units):
                if ctx.kinds[i] == "blank" or not t.strip() or i in ctx.locked:
                    if cur:
                        runs.append(cur)
                    cur = []
                    continue
                if cur and (ctx.blocks[i] != cur_block or len(cur) >= cap):
                    runs.append(cur)
                    cur = []
                cur.append(i)
                cur_block = ctx.blocks[i]
            if cur:
                runs.append(cur)
            return runs

        def run_block(self, units, run, ctx: Ctx, k: int):
            prof = ctx.profile
            unit = prof["unit"]
            hs = ctx.settings["humas"]
            gen = hs.get("gen") if hs.get("advanced") else OFFICIAL_GEN
            tries = max(1, min(5, int(hs.get("tries", 3))))
            texts = [units[i] for i in run]
            seps = [ctx.seps[i] for i in run]
            draft = U.run_text(texts, seps, unit)
            run_facts = [f for f in ctx.facts if F._matches(f, draft)]
            attempts = []
            accepted = None
            pool = []
            gate = ctx.gate or {}
            sp = SP.get() if gate.get("on") else None
            chosen = None
            for t in range(tries):
                ctx.progress(f"blok {k + 1} · percobaan {t + 1}/{tries}", None)
                raw = ctx.hub.humas_generate(draft, ctx.seed * 1000 + k * 10 + t, gen, bool(hs.get("chat")))
                cand, _ = ctx.repo.clean_text(raw)
                parts = U.resplit_run(cand, unit, len(run))
                if parts is None:
                    why = [f"jumlah {'baris' if unit == 'line' else 'satuan'} beda"]
                else:
                    why = run_problems(draft, U.run_text(parts, seps, unit), run_facts, prof, prof.get("language", "en"))
                att = {"why": why, "out": cand[:1500]}
                attempts.append(att)
                if why:
                    continue
                if sp is None:
                    accepted = parts
                    break
                g = sp.gate(draft, U.run_text(parts, seps, unit), gate.get("context", "blog"), gate.get("banned"),
                            lang=gate.get("lang", "en"), allow=gate.get("allow"))
                att["satpam"] = {"verdict": g["verdict"], "points": g["points"], "orig": g["orig_points"], "new": g["new"]}
                if gate.get("mode") == "catat" or g["verdict"] == "clean":
                    accepted, chosen = parts, g
                    break
                pool.append((g["penalty"], t, parts, g))
            if accepted is None and pool:
                ok_pool = [x for x in pool if x[3]["verdict"] == "no_worse"]
                pen_, t_, parts_, g_ = min(ok_pool or pool, key=lambda x: (x[0], x[1]))
                if ok_pool:
                    accepted, chosen = parts_, g_
                else:
                    attempts.append({"why": [f"satpam: semua keluaran lebih slop dari asli ({g_['orig_points']} → {g_['points']} poin"
                                             + (": " + ", ".join(g_["new"][:4]) if g_["new"] else "") + ")"], "out": "", "synthetic": True})
            out = list(units)
            if accepted:
                # pertahankan spasi awal baris asli (indentasi puisi)
                for i, new in zip(run, accepted):
                    lead = units[i][:len(units[i]) - len(units[i].lstrip())]
                    out[i] = lead + new
            last_why = "; ".join(attempts[-1]["why"]) if attempts else ""
            ids = [ctx.unit_ids[i] for i in run]
            n_gen = sum(1 for a in attempts if not a.get("synthetic"))
            sat = ""
            if chosen is not None:
                sat = f" · Satpam {chosen['verdict']} ({chosen['orig_points']} → {chosen['points']} poin)"
            if accepted:
                ctx.log("ok", f"blok {k + 1} ({ids[0]}–{ids[-1]}) ✓ diterima, percobaan {n_gen}{sat}")
            else:
                ctx.log("warn", f"blok {k + 1} ({ids[0]}–{ids[-1]}) ✗ ditolak ({last_why}), satuan asli dipakai")
            return out, {"block": k + 1, "units": ids, "accepted": accepted is not None, "tries": n_gen,
                         "reason": "" if accepted else last_why, "attempts": attempts,
                         "satpam": ({"verdict": chosen["verdict"], "points": chosen["points"], "orig": chosen["orig_points"]}
                                    if chosen is not None else None)}

    ''')
    return (f_meja_stations_humas_py,)


