@app.cell(hide_code=True)
def meja_stations_mlm_py(tulis):
    # meja/stations/mlm.py
    f_meja_stations_mlm_py = tulis("meja/stations/mlm.py", r'''
    """Redaktur Bahasa: MLM konsensus dua model, dan MLM repo sebagai pembanding (jalur R).

    Konsensus: kandidat dari model utama (top-k) hanya dipakai kalau juga muncul di top-k model pengecek.
    Kata yang termasuk fakta, kamus, frasa miring, atau satuan terkunci tidak pernah di-mask.
    """
    from __future__ import annotations

    import re
    from collections import Counter

    from .. import facts as F
    from .. import units as U
    from .base import Ctx, Station

    STOP = set("""a an the and or but if of to in on at by for with from as is are was were be been being it its this that these those
    i me my we our you your he she they them his her their not no so than then there here what which who whom when where why how all any
    each few more most other some such only own same too very can will just do does did has have had into over under again once up down
    out off about against between through during before after above below until while still since every would could should might must
    one ten none like yang dan di ke dari untuk dengan pada ini itu tidak sudah akan bisa juga ada saya kami kita mereka dia""".split())
    _ASCII_WORD = re.compile(r"[A-Za-z][A-Za-z'-]*[A-Za-z]|[A-Za-z]")


    def match_case(orig: str, new: str) -> str:
        if orig.isupper() and len(orig) > 1:
            return new.upper()
        if orig[:1].isupper():
            return new[:1].upper() + new[1:].lower()
        return new.lower()


    def _window(units: list[str], seps: list[str], blocks: list[int], i: int) -> tuple[str, int]:
        """Teks konteks (blok sebelum, blok ini, blok sesudah) dan posisi awal satuan i di dalamnya."""
        b = blocks[i]
        idx = [j for j in range(len(units)) if b - 1 <= blocks[j] <= b + 1]
        text, off = "", 0
        for j in idx:
            if j == i:
                off = len(text)
            text += units[j] + (seps[j] if j != idx[-1] else "")
        return text, off


    class MLM(Station):
        id = "mlm"
        label = "Redaktur Bahasa · MLM konsensus"
        office = "Redaktur Bahasa"
        model = True

        def run(self, units, ctx: Ctx):
            s = ctx.settings["mlm"]
            intensity = float(s.get("intensity", 0.2))
            main, check = s.get("model_main", "roberta-large"), s.get("model_check", "xlm-roberta-large")
            k_main, k_check, max_per = int(s.get("topk_main", 10)), int(s.get("topk_check", 20)), int(s.get("max_per_unit", 1))
            strict = s.get("strict", True)
            if intensity <= 0:
                return list(units), {"swaps": [], "eligible": 0}
            elig = []
            for i, t in enumerate(units):
                if ctx.kinds[i] == "blank" or i in ctx.locked or not t.strip():
                    continue
                spans = F.protected_spans(t, ctx.facts, ctx.kamus, ctx.italic)
                for m in _ASCII_WORD.finditer(t):
                    w = m.group(0)
                    if len(w) < 4 or w.lower() in STOP or "'" in w or "-" in w:
                        continue
                    if any(a < m.end() and m.start() < b for a, b in spans):
                        continue
                    elig.append((i, m.start(), m.end(), w))
            budget = max(1, round(len(elig) * intensity)) if elig else 0
            ctx.rng.shuffle(elig)
            per: Counter = Counter()
            changes = []
            tried = 0
            for i, a, b, w in elig:
                if len(changes) >= budget:
                    break
                if per[i] >= max_per:
                    continue
                tried += 1
                if tried % 5 == 0:
                    ctx.progress(f"Redaktur Bahasa · {len(changes)}/{budget} kata diganti", len(changes) / max(1, budget))
                text, off = _window(units, ctx.seps, ctx.blocks, i)
                masked = text[:off + a] + "<<MASK>>" + text[off + b:]
                cand_main = ctx.hub.mlm_topk(main, masked, k_main, orig=w)
                if not cand_main:
                    continue
                if strict and w.lower() not in {x.lower() for x in cand_main}:
                    continue  # model tidak menebak kata aslinya: slot ini terlalu khas, jangan disentuh
                chk = {x.lower() for x in ctx.hub.mlm_topk(check, masked, k_check, orig=w)}
                cands = [x for x in cand_main if x.lower() != w.lower() and x.lower()[:4] != w.lower()[:4]
                         and x.lower() in chk and x.lower() not in STOP]
                if not cands:
                    continue
                new = match_case(w, ctx.rng.choice(cands[:3]))
                changes.append((i, a, b, w, new))
                per[i] += 1
            out = list(units)
            for i, a, b, w, new in sorted(changes, key=lambda c: (c[0], -c[1])):
                out[i] = out[i][:a] + new + out[i][b:]
            swaps = [[ctx.unit_ids[i], w, new] for i, a, b, w, new in sorted(changes)]
            ctx.log("info", f"Redaktur Bahasa: {len(swaps)} kata diganti dari {len(elig)} yang boleh disentuh")
            return out, {"swaps": swaps, "eligible": len(elig), "strict": bool(strict)}


    class MLMRepo(Station):
        id = "mlm_repo"
        label = "Redaktur Bahasa · MLM repo (pembanding)"
        office = "Redaktur Bahasa"
        model = True

        def run(self, units, ctx: Ctx):
            level = float(ctx.settings["mlm"].get("intensity", 0.2))
            text = U.join(units, ctx.seps)
            new = ctx.hub.repo_mlm(text, level)
            parts = U.segment(new, ctx.profile["unit"])
            if len(parts) == len(units):
                out = [p.text for p in parts]
            else:  # struktur bergeser: ulang per satuan supaya tetap sejajar
                out = [ctx.hub.repo_mlm(t, level) if t.strip() else t for t in units]
            restored = 0
            for i in ctx.locked:
                if out[i] != units[i]:
                    out[i] = units[i]
                    restored += 1
            swaps = []
            for i, (a, b) in enumerate(zip(units, out)):
                wa, wb = a.split(), b.split()
                if len(wa) == len(wb):
                    swaps += [[ctx.unit_ids[i], x, y] for x, y in zip(wa, wb) if x != y]
            ctx.log("info", f"MLM repo: {len(swaps)} kata diganti (tanpa kunci fakta, cuma pembanding)")
            return out, {"swaps": swaps, "locked_restored": restored}

    ''')
    return (f_meja_stations_mlm_py,)


@app.cell(hide_code=True)
def meja_stations_replace_py(tulis):
    # meja/stations/replace.py
    f_meja_stations_replace_py = tulis("meja/stations/replace.py", r'''
    """Bagian Tata Usaha · cari-ganti kustom (teks biasa atau regex). Satuan terkunci dilewati."""
    from __future__ import annotations

    import re

    from ..util import UserError
    from .base import Ctx, Station


    class Replace(Station):
        id = "replace"
        label = "Tata Usaha · cari-ganti"
        office = "Bagian Tata Usaha"

        def run(self, units, ctx: Ctx):
            rules = [r for r in ctx.settings.get("replace") or [] if r.get("find")]
            out, n = [], 0
            for i, t in enumerate(units):
                if i in ctx.locked or not t:
                    out.append(t)
                    continue
                for r in rules:
                    if r.get("regex"):
                        try:
                            t, k = re.subn(r["find"], r.get("repl", ""), t)
                        except re.error as ex:
                            raise UserError(f"Regex cari-ganti '{r['find']}' tidak valid: {ex}")
                    else:
                        k = t.count(r["find"])
                        t = t.replace(r["find"], r.get("repl", ""))
                    n += k
                out.append(t)
            return out, {"replaced": n}

    ''')
    return (f_meja_stations_replace_py,)


@app.cell(hide_code=True)
def meja_suara_py(tulis):
    # meja/suara.py
    f_meja_suara_py = tulis("meja/suara.py", r'''
    """Suara: seperti apa tulisan yang dituju. Preset siap pakai, plus "Suara gue" yang diekstrak dari contoh tulisan asli.

    Dua sumbu, mengikuti avoid-ai-writing: *konteks* (seberapa ketat, lihat satpam.CONTEXTS) dan *suara* (bunyi tulisan).
    Modul ini menangani suara:

    - `fingerprint(teks)`: sidik jari gaya yang bisa dihitung tanpa model (panjang kalimat dan variasinya, kontraksi,
      tanda baca, kata ganti, kata fungsi, kosakata, frasa khas).
    - `PRESETS`: casual, professional, technical, warm, blunt (dari avoid-ai-writing) dan "manusia" (rambu statistik
      tulisan manusia umum). Rentang angkanya perkiraan kasar untuk peringatan, bukan kuota.
    - Suara gue: dibuat dari >= 150 kata contoh (ideal >= 500), disimpan lokal di MEJA_HOME/suara/suara_*.json.
      Contoh tulisan tidak pernah dikirim ke mana pun selain model lokal (Penelaah) kalau lo minta Voice Guide.
    - `match(fp, suara)`: kecocokan 0-100 dan fitur mana yang meleset.
    """
    from __future__ import annotations

    import json
    import math
    import re
    import time
    from collections import Counter
    from pathlib import Path

    from .util import UserError, slug, words

    FW_EN = ("the a an and but or so of to in on at for with from by as that this these those it its is are was were be been "
             "i me my we our you your he she they them their his her not no if then than just very really there here what "
             "which who when where how all some any more most can could would should will may might do did does have has had").split()
    FW_ID = ("yang dan di ke dari itu ini dengan untuk pada tidak ada akan juga saya aku kamu kita kami mereka dia ia sudah "
             "belum bisa harus karena jadi tapi atau kalau jika seperti dalam lebih sangat masih hanya pun lagi nya gak nggak").split()
    HEDGES = re.compile(r"\b(maybe|perhaps|might|probably|possibly|seems?|i think|i guess|sort of|kind of|arguably|likely|"
                        r"mungkin|sepertinya|kayaknya|barangkali|agaknya)\b", re.I)
    INTENS = re.compile(r"\b(very|really|so|extremely|incredibly|truly|absolutely|totally|deeply|highly|super|"
                        r"sangat|banget|sekali|amat|benar-benar)\b", re.I)
    CONTR = re.compile(r"\b\w+(?:'|’)(?:s|re|ve|ll|d|m|t)\b|\b\w+n(?:'|’)t\b", re.I)
    FIRST = re.compile(r"\b(i|me|my|mine|we|us|our|ours|saya|aku|gue|gw|kami|kita)\b", re.I)
    SECOND = re.compile(r"\b(you|your|yours|kamu|lo|lu|anda|kalian)\b", re.I)

    FEATURES = {
        "sent_mean": ("Rata-rata kata per kalimat", 1),
        "sent_cv": ("Variasi panjang kalimat (CV)", 2),
        "contractions": ("Kontraksi per 100 kata", 1),
        "comma": ("Koma per 1000 kata", 0),
        "semicolon": ("Titik koma per 1000 kata", 1),
        "colon": ("Titik dua per 1000 kata", 1),
        "dash": ("Em/en dash per 1000 kata", 1),
        "exclaim": ("Tanda seru per 1000 kata", 1),
        "question": ("Tanda tanya per 1000 kata", 1),
        "paren": ("Kurung per 1000 kata", 1),
        "word_len": ("Panjang kata rata-rata", 2),
        "ttr": ("Ragam kosakata (TTR per 200 kata)", 2),
        "first_person": ("Kata ganti orang pertama per 100 kata", 1),
        "second_person": ("Kata ganti orang kedua per 100 kata", 1),
        "hedges": ("Kata ragu per 100 kata", 2),
        "intensifiers": ("Kata penguat per 100 kata", 2),
        "lower_start": ("Kalimat diawali huruf kecil (%)", 0),
        "slop": ("Poin slop Satpam per 100 kata", 1),
    }

    PRESETS = {
        "manusia": {"label": "Manusia umum", "desc": "Panjang kalimat naik-turun, kosakata wajar, tanpa kata dan pola khas AI. "
                    "Tidak memaksakan persona.",
                    "guide": "Natural human prose: sentence lengths vary, vocabulary is ordinary and specific, no stock AI "
                             "phrasing, no staged rhythm. Do not impose a persona; keep the writer's existing register.",
                    "targets": {"sent_cv": [0.5, 1.4], "ttr": [0.48, 0.78], "slop": [0, 1.5], "dash": [0, 4]}},
        "casual": {"label": "Santai (casual)", "desc": "Kontraksi, kalimat langsung seperti ngobrol, kata sehari-hari.",
                   "guide": "Casual: contractions, direct conversational sentences, everyday words; keep concrete touches "
                            "the source has. Do not force fragments or slang.",
                   "targets": {"contractions": [2.0, 12], "sent_mean": [6, 18], "sent_cv": [0.45, 1.5], "slop": [0, 1.5]}},
        "professional": {"label": "Profesional", "desc": "Kalimat aktif, klaim konkret, sedikit penguat, ajakan tetap jelas.",
                         "guide": "Professional: active voice when the actor matters, concrete claims from the source, "
                                  "little padding, real uncertainty kept, no hype.",
                         "targets": {"contractions": [0, 3], "sent_mean": [12, 24], "sent_cv": [0.35, 1.1],
                                     "intensifiers": [0, 1.0], "slop": [0, 1.0]}},
        "technical": {"label": "Teknis", "desc": "\"X adalah Y\", istilah tepat dipertahankan, tanpa hiasan.",
                      "guide": "Technical: plain copulas (X is Y) instead of 'serves as'/'stands as', precise terms kept, "
                               "one idea per sentence where it helps, no decoration.",
                      "targets": {"sent_mean": [10, 24], "intensifiers": [0, 0.6], "hedges": [0, 1.2], "contractions": [0, 2],
                                  "slop": [0, 1.0]}},
        "warm": {"label": "Hangat", "desc": "Menyapa pembaca (you) kalau sumbernya begitu, tempo tenang, tanpa empati palsu.",
                 "guide": "Warm: address the reader where the source already does, unhurried cadence, keep the source's "
                          "acknowledgment, no performative empathy openers.",
                 "targets": {"second_person": [0.6, 8], "contractions": [1, 10], "sent_mean": [8, 20], "slop": [0, 1.5]}},
        "blunt": {"label": "Lugas (blunt)", "desc": "Klaim di depan, kalimat pendek, ragu dan penguat dibuang kecuali perlu.",
                  "guide": "Blunt: lead with the claim, short direct sentences, cut windups and stacked hedges but keep "
                           "qualifiers that carry real uncertainty, no manufactured staccato.",
                  "targets": {"sent_mean": [5, 15], "hedges": [0, 0.5], "intensifiers": [0, 0.5], "dash": [0, 1],
                              "slop": [0, 1.0]}},
    }
    MIN_WORDS, GOOD_WORDS = 150, 500


    def _sentences(text: str) -> list[str]:
        parts = re.split(r"(?<=[.!?…])\s+|\n+", text)
        return [p.strip() for p in parts if words(p)]


    def fingerprint(text: str, lang: str = "en", slop_points: float | None = None) -> dict:
        ws = words(text)
        n = len(ws)
        sents = _sentences(text)
        lens = [len(words(s)) for s in sents]
        fp: dict = {"words": n, "sentences": len(sents)}
        if not n:
            return fp
        m = sum(lens) / len(lens) if lens else 0
        fp["sent_mean"] = round(m, 1)
        fp["sent_cv"] = round(math.sqrt(sum((x - m) ** 2 for x in lens) / len(lens)) / m, 3) if len(lens) >= 3 and m else None
        per100 = lambda c: round(100.0 * c / n, 2)  # noqa: E731
        per1000 = lambda c: round(1000.0 * c / n, 1)  # noqa: E731
        fp["contractions"] = per100(len(CONTR.findall(text)))
        fp["comma"] = per1000(text.count(","))
        fp["semicolon"] = per1000(text.count(";"))
        fp["colon"] = per1000(len(re.findall(r":(?!//)", text)))
        fp["dash"] = per1000(len(re.findall("[—–]|\\s--\\s", text)))
        fp["exclaim"] = per1000(text.count("!"))
        fp["question"] = per1000(text.count("?"))
        fp["paren"] = per1000(text.count("("))
        fp["word_len"] = round(sum(len(w) for w in ws) / n, 2)
        low = [w.lower().strip("'’") for w in ws]
        if n >= 200:
            wins = [len(set(low[i:i + 200])) / 200 for i in range(0, n - 199, 100)]
            fp["ttr"] = round(sum(wins) / len(wins), 3)
        else:
            fp["ttr"] = round(len(set(low)) / n, 3) if n >= 40 else None
        fp["first_person"] = per100(len(FIRST.findall(text)))
        fp["second_person"] = per100(len(SECOND.findall(text)))
        fp["hedges"] = per100(len(HEDGES.findall(text)))
        fp["intensifiers"] = per100(len(INTENS.findall(text)))
        fp["lower_start"] = round(100.0 * sum(1 for s in sents if s[:1].islower()) / len(sents)) if sents else 0
        if slop_points is not None:
            fp["slop"] = round(100.0 * slop_points / n, 2)
        fw = FW_ID if lang == "id" else FW_EN
        cnt = Counter(low)
        tot = sum(cnt[w] for w in fw) or 1
        fp["fw"] = {w: round(cnt[w] / tot, 4) for w in fw if cnt[w]}
        opens = Counter((words(s)[0].lower().strip("\"'“‘") if words(s) else "") for s in sents)
        fp["openers"] = [[w, c] for w, c in opens.most_common(8) if w]
        fp["signature"] = signature_phrases(low, set(fw))
        return fp


    def signature_phrases(low: list[str], fw: set[str], top: int = 12) -> list[str]:
        grams = Counter()
        for size in (3, 2):
            for i in range(len(low) - size + 1):
                g = low[i:i + size]
                if all(w in fw for w in g) or any(not re.match(r"[\w'’-]+$", w) for w in g):
                    continue
                grams[" ".join(g)] += 1
        out = []
        for g, c in grams.most_common(60):
            if c < 2:
                break
            if any(g in o for o in out):
                continue
            out.append(g)
            if len(out) >= top:
                break
        return out


    def _cos(a: dict, b: dict) -> float | None:
        if not a or not b:
            return None
        keys = set(a) | set(b)
        dot = sum(a.get(k, 0) * b.get(k, 0) for k in keys)
        na = math.sqrt(sum(v * v for v in a.values()))
        nb = math.sqrt(sum(v * v for v in b.values()))
        return dot / (na * nb) if na and nb else None


    def derive_targets(fp: dict) -> dict:
        """Rentang 'masih terdengar seperti lo' dari sidik jari sendiri."""
        t = {}
        spec = {"sent_mean": (0.35, 2.0), "sent_cv": (0.35, 0.12), "contractions": (0.6, 0.6), "comma": (0.45, 8),
                "dash": (0.7, 1.0), "semicolon": (0.8, 0.8), "colon": (0.8, 0.8), "exclaim": (0.8, 0.8),
                "question": (0.8, 0.8), "word_len": (0.12, 0.15), "ttr": (0.15, 0.04), "first_person": (0.6, 0.5),
                "second_person": (0.7, 0.5), "hedges": (0.7, 0.4), "intensifiers": (0.7, 0.4)}
        for k, (rel, ab) in spec.items():
            v = fp.get(k)
            if v is None:
                continue
            d = max(abs(v) * rel, ab)
            t[k] = [round(max(0.0, v - d), 3), round(v + d, 3)]
        t["slop"] = [0, max(1.0, round((fp.get("slop") or 0) * 1.5, 2))]
        return t


    def match(fp: dict, voice: dict) -> dict:
        targets = voice.get("targets") or {}
        pens, off = [], []
        for k, (lo, hi) in targets.items():
            v = fp.get(k)
            if v is None:
                continue
            if lo <= v <= hi:
                pens.append(0.0)
                continue
            width = max(hi - lo, 0.15 * max(abs(lo), abs(hi), 1.0))
            d = (lo - v) if v < lo else (v - hi)
            p = min(1.0, d / width)
            pens.append(p)
            off.append({"key": k, "label": FEATURES.get(k, (k, 1))[0], "value": v, "lo": lo, "hi": hi,
                        "dir": "kurang" if v < lo else "lebih"})
        ref = (voice.get("fingerprint") or {}).get("fw")
        c = _cos(fp.get("fw") or {}, ref) if ref else None
        if c is not None and fp.get("words", 0) >= 40:
            pens.append(max(0.0, min(1.0, (0.92 - c) / 0.35)))
            if c < 0.8:
                off.append({"key": "fw", "label": "Pola kata fungsi", "value": round(c, 2), "lo": 0.8, "hi": 1.0, "dir": "kurang"})
        if not pens:
            return {"score": None, "off": [], "n": 0}
        score = round(100 * (1 - sum(pens) / len(pens)))
        off.sort(key=lambda x: -abs((x["value"] - (x["lo"] if x["dir"] == "kurang" else x["hi"])) / max(1e-9, x["hi"] - x["lo"] or 1)))
        return {"score": score, "off": off[:6], "n": len(pens)}


    class VoiceStore:
        def __init__(self, folder: Path):
            self.dir = Path(folder)
            self.dir.mkdir(parents=True, exist_ok=True)

        def _path(self, vid: str) -> Path:
            return self.dir / f"suara_{vid}.json"

        def list(self) -> list[dict]:
            out = []
            for p in sorted(self.dir.glob("suara_*.json")):
                try:
                    v = json.loads(p.read_text("utf-8"))
                    out.append(v)
                except Exception:
                    continue
            out.sort(key=lambda v: v.get("updated", ""), reverse=True)
            return out

        def get(self, vid: str) -> dict | None:
            p = self._path(vid)
            if not p.exists():
                return None
            try:
                return json.loads(p.read_text("utf-8"))
            except Exception:
                return None

        def save(self, v: dict) -> dict:
            v["updated"] = time.strftime("%Y-%m-%dT%H:%M:%S")
            self._path(v["id"]).write_text(json.dumps(v, ensure_ascii=False, indent=1), "utf-8")
            return v

        def delete(self, vid: str):
            p = self._path(vid)
            if p.exists():
                p.unlink()


    def build_custom(name: str, samples: str, lang: str, never_user: list[str], tier1: list[str], slop_points: float,
                     vid: str | None = None, old: dict | None = None) -> dict:
        samples = samples.strip()
        n = len(words(samples))
        if n < MIN_WORDS:
            raise UserError(f"Contoh tulisannya baru {n} kata. Butuh minimal {MIN_WORDS} kata (ideal {GOOD_WORDS}+): "
                            "chat, email, catatan, apa aja yang lo tulis sendiri tanpa dibantu AI.")
        fp = fingerprint(samples, lang, slop_points)
        low = samples.lower()
        auto_never = sorted({w for w in tier1 if not re.search(r"(?<![\w'-])" + re.escape(w.lower()) + r"(?![\w'-])", low)})
        vid = vid or (slug(name)[:30] or "suara") + "-" + time.strftime("%m%d%H%M")
        v = dict(old or {})
        v.update({"id": vid, "kind": "custom", "label": name.strip()[:60] or "Suara gue", "lang": lang, "samples": samples,
                  "words": n, "mode": "lengkap" if n >= GOOD_WORDS else "cepat", "fingerprint": fp,
                  "targets": derive_targets(fp), "never_auto": auto_never,
                  "never_user": [w.strip() for w in never_user if w and w.strip()][:200],
                  "signature": fp.get("signature", []),
                  "created": (old or {}).get("created") or time.strftime("%Y-%m-%dT%H:%M:%S")})
        if old and old.get("samples") != samples:
            v["guide"], v["validation"] = None, None
        v.setdefault("guide", None)
        v.setdefault("validation", None)
        v["desc"] = describe(v)
        return v


    def describe(v: dict) -> str:
        fp = v.get("fingerprint") or {}
        bits = []
        if fp.get("sent_mean") is not None:
            bits.append(f"kalimat rata-rata {fp['sent_mean']} kata")
        if fp.get("sent_cv") is not None:
            bits.append("panjangnya " + ("naik-turun" if fp["sent_cv"] >= 0.55 else "cenderung rata"))
        if fp.get("contractions") is not None:
            bits.append("banyak kontraksi" if fp["contractions"] >= 2 else "jarang kontraksi")
        if (fp.get("first_person") or 0) >= 1.5:
            bits.append("sering pakai \"aku/gue/I\"")
        if (fp.get("dash") or 0) < 0.5:
            bits.append("hampir tanpa em dash")
        return f"Dari {v.get('words', 0)} kata contoh: " + ", ".join(bits) + "."


    def never_list(voice: dict) -> list[str]:
        if voice.get("kind") != "custom":
            return []
        return list(dict.fromkeys((voice.get("never_user") or []) + (voice.get("never_auto") or [])))


    def guide_text(voice: dict) -> str:
        """Teks pedoman suara untuk Penelaah (bahasa Inggris, ringkas)."""
        if voice.get("kind") != "custom":
            return f"TARGET VOICE: {voice['label']}. {voice.get('guide', '')}"
        fp = voice.get("fingerprint") or {}
        lines = [f"TARGET VOICE: the writer's own voice ('{voice['label']}'), measured from {voice.get('words')} words of "
                 "their real writing."]
        keys = ("sent_mean", "sent_cv", "contractions", "dash", "first_person", "second_person", "hedges", "intensifiers")
        lines.append("Measured habits: " + "; ".join(f"{FEATURES[k][0]} {fp.get(k)}" for k in keys if fp.get(k) is not None) + ".")
        if voice.get("signature"):
            lines.append("Phrases they actually use: " + ", ".join(f'"{s}"' for s in voice["signature"][:10]) + ".")
        nv = never_list(voice)
        if nv:
            lines.append("Words they never use (flag as off-voice): " + ", ".join(nv[:40]) + ".")
        g = voice.get("guide") or {}
        if isinstance(g, dict) and g:
            for k in ("role", "energy"):
                if g.get(k):
                    lines.append(f"{k.title()}: {g[k]}")
            for k in ("traits", "do", "dont"):
                if g.get(k):
                    lines.append(f"{k.upper()}: " + "; ".join(str(x) for x in g[k][:6]))
        return "\n".join(lines)


    def public(voice: dict) -> dict:
        """Versi aman untuk widget: tanpa teks contoh."""
        v = {k: val for k, val in voice.items() if k not in ("samples",)}
        if "fingerprint" in v and v["fingerprint"]:
            v["fingerprint"] = {k: val for k, val in v["fingerprint"].items() if k not in ("fw",)}
        return v


    def resolve(sid: str, store: VoiceStore) -> dict:
        if sid in PRESETS:
            return {"id": sid, "kind": "preset", **PRESETS[sid]}
        if sid and sid != "otomatis":
            v = store.get(sid)
            if v:
                return v
        if sid == "otomatis" or not sid:
            mine = [v for v in store.list() if (v.get("validation") or {}).get("ok") is not False]
            if mine:
                return mine[0]
        return {"id": "manusia", "kind": "preset", **PRESETS["manusia"]}


    def options(store: VoiceStore) -> list[dict]:
        out = [{"id": "otomatis", "label": "Otomatis", "kind": "auto",
                "desc": "Pakai Suara gue kalau sudah ada, kalau belum pakai Manusia umum."}]
        out += [{"id": k, "label": v["label"], "kind": "preset", "desc": v["desc"]} for k, v in PRESETS.items()]
        out += [{"id": v["id"], "label": v.get("label", v["id"]), "kind": "custom", "desc": v.get("desc", ""),
                 "words": v.get("words"), "mode": v.get("mode"), "validated": (v.get("validation") or {}).get("ok")}
                for v in store.list()]
        return out

    ''')
    return (f_meja_suara_py,)


@app.cell(hide_code=True)
def meja_sulap_py(tulis):
    # meja/sulap.py
    f_meja_sulap_py = tulis("meja/sulap.py", r'''
    """Sulap: kerja di belakang layar yang menyatukan Satpam, Suara, dan Penelaah.

    - `gate_info(k, b)`     : setelan penyaring Humas (konteks, daftar larangan) untuk satu berkas.
    - `candidates(b, i)`    : teks alternatif berbeda untuk satuan ke-i beserta nama varian yang menghasilkannya.
    - `telaah_todo / telaah_unit`: Penelaah menilai alternatif per satuan (label teracak, kutipan divalidasi).
    - `rank(k, b)`          : peringkat alternatif per satuan: fakta wajib → poin Satpam → catatan Penelaah → geser makna.
    - `auto_pick(k, b)`     : pilih alternatif terbaik per satuan (bisa diubah user kapan saja).
    - `snapshot(k, b)`      : state `sulap` untuk widget.
    """
    from __future__ import annotations

    import json
    import os
    import time

    from . import facts as F
    from . import rubrik as RB
    from . import satpam as SP
    from . import suara as SU
    from . import units as U
    from .textcheck import change_pct, run_problems
    from .util import hhmm, now, short_hash, words

    PEN_DEFAULT = {"model": "Qwen/Qwen3.8-27B-FP8", "load": "otomatis", "skills": "utuh", "skills_dir": "", "thinking": "dipandu"}


    class Memori:
        """Memori redaksi: keputusan editor (pilihan yang menimpa ★, saran pensil diterima/ditolak), disimpan lokal.

        Dipakai sebagai contoh di prompt Penelaah supaya penilaiannya lama-lama ikut selera lo. Berisi potongan naskah,
        jadi hanya ditulis ke MEJA_HOME/memori.json (tidak pernah ke repo atau arsip yang dibagikan).
        """

        def __init__(self, path):
            self.path = path
            try:
                items = json.loads(self.path.read_text("utf-8"))
                self.items = [x for x in items if isinstance(x, dict)] if isinstance(items, list) else []
            except Exception:
                self.items = []

        def add(self, kind: str, **data):
            it = {"t": now().strftime("%d-%m %H:%M"), "kind": kind,
                  **{k: (str(v)[:400] if isinstance(v, str) else v) for k, v in data.items()}}
            if self.items and {k: v for k, v in self.items[-1].items() if k != "t"} == {k: v for k, v in it.items() if k != "t"}:
                return
            self.items = (self.items + [it])[-200:]
            self._save()

        def recent(self, n: int = 6) -> list[dict]:
            return self.items[-n:]

        def clear(self):
            self.items = []
            self._save()

        def _save(self):
            try:
                self.path.write_text(json.dumps(self.items, ensure_ascii=False, indent=0), "utf-8")
            except OSError:
                pass


    class Aturan:
        """Aturan gue: aturan tulisan dan kata larangan milik editor, berlaku di semua berkas (MEJA_HOME/aturan.json)."""

        def __init__(self, path):
            self.path = path
            try:
                d = json.loads(self.path.read_text("utf-8"))
            except Exception:
                d = {}
            d = d if isinstance(d, dict) else {}
            self.rules = [str(x) for x in (d.get("rules") if isinstance(d.get("rules"), list) else []) if str(x).strip()]
            self.never = [str(x) for x in (d.get("never") if isinstance(d.get("never"), list) else []) if str(x).strip()]

        def set(self, rules: list[str], never: list[str]):
            self.rules = list(dict.fromkeys(r.strip()[:240] for r in rules if r and r.strip()))[:40]
            self.never = list(dict.fromkeys(w.strip()[:60] for w in never if w and w.strip()))[:200]
            try:
                self.path.write_text(json.dumps({"rules": self.rules, "never": self.never}, ensure_ascii=False, indent=1), "utf-8")
            except OSError:
                pass


    class Identitas:
        """Data diri yang TIDAK boleh muncul di naskah/file kiriman (nama, email, kampus, nomor HP).

        Disimpan hanya di MEJA_HOME/identitas.json (izin 600), tidak pernah ikut arsip, profil, paket, atau log.
        Di layar ditampilkan tersamar ("Na**").
        """

        def __init__(self, path):
            self.path = path
            try:
                d = json.loads(self.path.read_text("utf-8"))
                items = d.get("items") if isinstance(d, dict) else d
            except Exception:
                items = []
            self.items = [str(x).strip() for x in (items if isinstance(items, list) else []) if str(x).strip()]

        def set(self, items: list[str]):
            self.items = list(dict.fromkeys(str(x).strip()[:120] for x in items if str(x).strip()))[:60]
            try:
                self.path.write_text(json.dumps({"items": self.items}, ensure_ascii=False), "utf-8")
                os.chmod(self.path, 0o600)
            except OSError:
                pass

        @staticmethod
        def mask(x: str) -> str:
            x = str(x)
            return x[:2] + "*" * max(2, min(6, len(x) - 2)) if len(x) > 2 else "**"

        def public(self) -> dict:
            return {"n": len(self.items), "masked": [self.mask(x) for x in self.items]}


    # ---------- setelan efektif ----------
    def context_id(b) -> str:
        s = b.settings.get("satpam") or {}
        return SP.context_for(b.profile, None if s.get("context", "otomatis") == "otomatis" else s.get("context"))


    def voice(k, b) -> dict:
        return SU.resolve((b.settings.get("suara") or {}).get("id", "otomatis"), k.voices)


    def banned(k, b) -> list[str]:
        return list(dict.fromkeys(list(b.profile.get("banned", [])) + SU.never_list(voice(k, b)) + list(k.aturan.never)))


    def gate_info(k, b) -> dict:
        s = b.settings
        on = bool((s.get("sulap") or {}).get("satpam", True))
        return {"on": on, "mode": (s.get("satpam") or {}).get("mode", "saring"), "context": context_id(b),
                "banned": banned(k, b) if on else [], "lang": lang_of(b), "allow": refrain_phrases(b)}


    def gate_sig(k, b) -> str:
        g = gate_info(k, b)
        return short_hash(json.dumps(g, sort_keys=True, ensure_ascii=False), 8) if g["on"] else "off"


    def voice_guide(k, b) -> str:
        return SU.guide_text(voice(k, b))


    def context_note(b) -> str:
        cx = SP.CONTEXTS[context_id(b)]
        lang = b.profile.get("language", "en")
        kind = "a poem (line breaks and stanza breaks are part of the form)" if b.profile.get("verse") else \
            f"{b.profile.get('name', 'prose')}"
        return f"{kind}; strictness profile '{context_id(b)}' ({cx['note']}); language {lang}."


    # ---------- kandidat per satuan ----------
    def candidates(b, i: int) -> list[dict]:
        u = b.units[i]
        out: dict[str, dict] = {}
        for v in b.variants:
            if i >= len(v.get("units", [])):
                continue
            t = v["units"][i]
            if t not in out:
                out[t] = {"text": t, "names": []}
            out[t]["names"].append(v["name"])
        if u["text"] not in out:
            out = {u["text"]: {"text": u["text"], "names": ["ASLI"]}, **out}
        return list(out.values())


    def _unit_facts(b, text: str) -> list[dict]:
        return [f for f in b.facts if F._matches(f, text)]


    def review_sig(k, b) -> str:
        """Suara + Aturan gue + bahan bacaan: kalau salah satunya berubah, telaah lama tidak dipakai lagi."""
        p = b.settings.get("penelaah") or {}
        raw = json.dumps([SU.guide_text(voice(k, b)), k.aturan.rules, banned(k, b), p.get("skills", "utuh"),
                          p.get("skills_dir", "")], ensure_ascii=False)
        return voice(k, b)["id"] + "|" + short_hash(raw, 8)


    def text_key(b, uid: str, text: str, vid: str, ctx: str) -> str:
        return short_hash(f"{RB.VERSION}|{uid}|{vid}|{ctx}|{text}", 14)


    def set_key(b, uid: str, texts: list[str], vid: str, ctx: str) -> str:
        return short_hash(f"{RB.VERSION}|{uid}|{vid}|{ctx}|" + "␞".join(sorted(texts)), 14)


    def penelaah_on(b) -> bool:
        return bool((b.settings.get("sulap") or {}).get("telaah", True))


    def telaah_todo(k, b, scope: str = "varian") -> list[str]:
        """Satuan yang perlu ditelaah. scope 'varian': satuan dengan >= 2 alternatif. scope 'final': teks final per satuan."""
        if not b.units:
            return []
        vid, ctx = review_sig(k, b), context_id(b)
        tel = b.telaah or {}
        todo = []
        if scope == "final":
            _, funits = k.final_text_units(b)
            if funits is None:
                return []
            for u, t in zip(b.units, funits):
                if u["kind"] == "blank" or not t.strip():
                    continue
                ent = (tel.get("texts") or {}).get(text_key(b, u["id"], t, vid, ctx))
                if ent is None or (ent.get("error") and ent.get("tries", 1) < 2):
                    todo.append(u["id"])
            return todo
        locked = set(b.locks)
        for i, u in enumerate(b.units):
            if u["kind"] == "blank" or u["id"] in locked:
                continue
            cs = candidates(b, i)
            if len(cs) < 2:
                continue
            key = set_key(b, u["id"], [c["text"] for c in cs], vid, ctx)
            ent = (tel.get("rank") or {}).get(u["id"]) or {}
            if ent.get("key") != key or (ent.get("error") and ent.get("tries", 1) < 2):
                todo.append(u["id"])
        return todo


    def reset_errors(b):
        """Telaah yang gagal boleh dicoba lagi (dipanggil saat user menekan tombol telaah)."""
        tel = b.telaah or {}
        for ent in list((tel.get("texts") or {}).values()) + list((tel.get("rank") or {}).values()):
            if ent.get("error"):
                ent["tries"] = 0


    def _skills(b) -> str:
        p = b.settings.get("penelaah") or {}
        if p.get("skills", "utuh") != "utuh":
            return ""
        txt, _ = RB.load_skills(p.get("skills_dir") or "")
        return txt


    def system_for(k, b) -> str:
        """System prompt Penelaah yang sama untuk semua tugas di satu berkas (bisa di-cache sekali)."""
        return RB.system_prompt(context_note=context_note(b), voice_guide=voice_guide(k, b), skills_text=_skills(b),
                                extra_rules=k.aturan.rules, extra_never=banned(k, b))


    def memory_for(k) -> str:
        return RB.memory_text(k.memori.recent(6))


    def _chat_json(k, messages: list[dict], seed: int, b=None, task: str = "TELAAH") -> tuple[dict | None, str]:
        """Panggil Penelaah dan baca JSON-nya. Thinking 'dipandu' diisi rubrik lebih dulu; kalau penalarannya tidak
        selesai jadi JSON, diulang sekali tanpa thinking, lalu sekali lagi dengan permintaan JSON tegas."""
        mode = ((b.settings.get("penelaah") if b is not None else None) or {}).get("thinking", "dipandu")
        want = {"TELAAH": "candidates", "PENSIL": "replace", "SUARA": "role"}.get(task)
        raw = k.hub.penelaah_chat(messages, seed, thinking=mode, prefill=RB.SCAFFOLD.get(task, "") if mode == "dipandu" else "")
        data = RB.extract_json(raw, want)
        if data is None and mode != "mati":
            raw = k.hub.penelaah_chat(messages, seed + 1, thinking="mati")
            data = RB.extract_json(raw, want)
        if data is None:
            raw2 = k.hub.penelaah_chat(messages + [{"role": "assistant", "content": raw[-2000:]},
                                                   {"role": "user", "content": "That was not the requested JSON object. "
                                                                               "Return ONLY the JSON object."}],
                                       seed + 2, thinking="mati")
            data = RB.extract_json(raw2, want)
            raw = raw2
        return data, raw


    def telaah_unit(k, b, uid: str, scope: str = "varian") -> dict:
        """Satu panggilan Penelaah untuk satu satuan. Hasil disimpan per teks (bisa dipakai ulang lintas varian)."""
        idx = next(i for i, u in enumerate(b.units) if u["id"] == uid)
        u = b.units[idx]
        vid, ctx = review_sig(k, b), context_id(b)
        if scope == "final":
            _, funits = k.final_text_units(b)
            texts = [funits[idx]] if funits is not None else [u["text"]]
            names = {texts[0]: ["FINAL"]}
        else:
            cs = candidates(b, idx)
            texts = [c["text"] for c in cs]
            names = {c["text"]: c["names"] for c in cs}
        seed = int(b.settings.get("seed", 7)) * 7919 + idx
        labels = RB.labels_for(texts, seed)
        before = "".join(x["text"] + s for x, s in zip(b.units[max(0, idx - 3):idx], b.seps[max(0, idx - 3):idx]))
        after = "".join(x["text"] + s for x, s in zip(b.units[idx + 1:idx + 4], b.seps[idx + 1:idx + 4]))
        msgs = RB.telaah_messages(system=system_for(k, b), source=u["text"], before=before, after=after, cands=labels,
                                  facts=[f["text"] for f in _unit_facts(b, u["text"])], lang=b.profile.get("language", "en"),
                                  memory=memory_for(k))
        t0 = time.time()
        data, raw = _chat_json(k, msgs, seed, b, "TELAAH")
        tel = b.telaah
        tel.setdefault("texts", {})
        tel.setdefault("rank", {})
        tel["model"] = (b.settings.get("penelaah") or {}).get("model")
        tel["t"] = now().strftime("%d-%m %H:%M")
        if data is None:
            for t in texts:
                prev = tel["texts"].get(text_key(b, uid, t, vid, ctx)) or {}
                tel["texts"][text_key(b, uid, t, vid, ctx)] = {"uid": uid, "error": "keluaran Penelaah bukan JSON", "t": hhmm(),
                                                               "tries": int(prev.get("tries", 0)) + 1}
            if scope != "final":
                prev = tel["rank"].get(uid) or {}
                tel["rank"][uid] = {"key": set_key(b, uid, texts, vid, ctx), "order": [], "note": "", "error": True,
                                    "tries": int(prev.get("tries", 0)) + 1 if prev.get("error") else 1}
            k.log("warn", f"Telaah {uid}: keluaran bukan JSON, dilewati", "TELAAH")
            return {"ok": False}
        res, stats = RB.validate_telaah(data, labels, u["text"], RB.custom_rule_names(k.aturan.rules))
        order = []
        for lab in res["ranking"]:
            t = labels[lab]
            order.append(text_key(b, uid, t, vid, ctx))
        for lab, t in labels.items():
            r = res["cands"][lab]
            tel["texts"][text_key(b, uid, t, vid, ctx)] = {"uid": uid, "names": names.get(t, []), **r, "t": hhmm()}
        if scope != "final":
            tel["rank"][uid] = {"key": set_key(b, uid, texts, vid, ctx), "order": order, "note": res["note"]}
        tel.setdefault("stats", {"dropped": 0, "kept": 0, "calls": 0, "secs": 0.0})
        tel["stats"]["dropped"] += stats["dropped"]
        tel["stats"]["kept"] += stats["kept"]
        tel["stats"]["calls"] += 1
        tel["stats"]["secs"] = round(tel["stats"]["secs"] + time.time() - t0, 1)
        if stats["dropped"]:
            k.log("info", f"Telaah {uid}: {stats['dropped']} catatan tanpa kutipan valid dibuang", "TELAAH")
        b._rank_cache = None
        return {"ok": True, "stats": stats}


    # ---------- peringkat ----------
    def _drift_pen(pct: float) -> float:
        return 2.0 if pct > 75 else (1.0 if pct > 60 else 0.0)


    def _puisi():
        try:
            from . import puisi as PU
            return PU
        except ImportError:
            return None


    def is_verse(b) -> bool:
        return bool(b.profile.get("verse") or b.profile.get("unit") == "line")


    def refrain_phrases(b) -> list[str]:
        """Pengulangan yang disengaja di naskah asli (refrain, anafora): tidak dihitung slop."""
        PU = _puisi()
        if PU is None or not b.units:
            return []
        key = short_hash(b.clean or "", 10)
        c = getattr(b, "_refrain_cache", None)
        if c and c[0] == key:
            return c[1]
        try:
            out = list(PU.refrains([u["text"] for u in b.units], lang_of(b)).get("phrases") or [])
        except Exception:  # noqa: BLE001
            out = []
        b._refrain_cache = (key, out)
        return out


    def verse_check(b, i: int, text: str) -> dict | None:
        """Jaga rima/suku kata/refrain kalau baris i diganti `text` (puisi saja)."""
        PU = _puisi()
        if PU is None or not is_verse(b):
            return None
        orig = [u["text"] for u in b.units]
        new = orig[:i] + [text] + orig[i + 1:]
        try:
            return PU.verse_guard(orig, new, lang_of(b))
        except Exception:  # noqa: BLE001
            return None


    def rank(k, b) -> dict:
        if not b.units or len(b.variants) < 2:
            return {}
        gi = gate_info(k, b)
        ban = banned(k, b)  # kata larangan tetap dihitung walau Satpam di Humas dimatikan
        vid, ctx = review_sig(k, b), gi["context"]
        tel = b.telaah or {}
        key = short_hash(json.dumps([[x["name"], x.get("sig"), x.get("t"), short_hash(x.get("text", ""), 8)] for x in b.variants],
                                    ensure_ascii=False)
                         + json.dumps([ctx, ban, vid, b.locks, b.profile.get("style"), b.profile.get("language"), is_verse(b), lang_of(b), refrain_phrases(b),
                                       sorted([str(f.get("pattern") or f["text"]), str(f.get("kind")), bool(f.get("confirmed"))]
                                              for f in b.facts)], sort_keys=True, ensure_ascii=False)
                         + str(len(tel.get("texts") or {})) + str(len(tel.get("rank") or {})), 16)
        cache = getattr(b, "_rank_cache", None)
        if cache and cache[0] == key:
            return cache[1]
        sp = SP.get()
        lang = b.profile.get("language", "en")
        locked = set(b.locks)
        out = {}
        for i, u in enumerate(b.units):
            if u["kind"] == "blank":
                continue
            orig = u["text"]
            cs = candidates(b, i)
            if len(cs) < 2:
                continue
            ufacts = _unit_facts(b, orig)
            base = sp_analyze(k, b, orig, unit_level=True, allow=refrain_phrases(b))
            base_terms = sp.terms(base)
            order = ((tel.get("rank") or {}).get(u["id"]) or {}).get("order") or []
            rows = []
            for c in cs:
                t = c["text"]
                is_orig = t == orig
                excluded = None
                if not is_orig:
                    if u["id"] in locked:
                        excluded = "satuan dikunci"
                    else:
                        why = run_problems(orig, t, ufacts, b.profile, lang)
                        if why:
                            excluded = "; ".join(why)
                a = base if is_orig else sp_analyze(k, b, t, unit_level=True, allow=refrain_phrases(b))
                new = sorted(x[1] for x in (sp.terms(a) - base_terms))
                vg = None if is_orig else verse_check(b, i, t)
                vnotes = (list(vg.get("issues") or []) + list(vg.get("warnings") or [])) if vg else []
                vpen = (3.0 * len(vg.get("issues") or []) + 1.0 * len(vg.get("warnings") or [])) if vg else 0.0
                tk = text_key(b, u["id"], t, vid, ctx)
                tl = (tel.get("texts") or {}).get(tk)
                pct = 0.0 if is_orig else change_pct(orig, t)
                rows.append({"names": c["names"], "key": tk, "points": a["points"], "n": a["n"],
                             "items": [{"label": x["label"], "text": x["text"]} for x in a["items"] if x["type"] not in SP.DOC_LEVEL][:8],
                             "new": new[:8], "pct": pct, "excluded": excluded, "asli": is_orig, "_pen": RB.penalty(tl),
                             "verse": vnotes[:4],
                             "_base": a["points"] + 2.0 * len(new) + _drift_pen(pct) + (0.4 * order.index(tk) if tk in order else 0.0)
                             + vpen - (1.0 if is_orig else 0.0),
                             "telaah": ({kk: tl.get(kk) for kk in ("findings", "grammar", "meaning", "voice", "verdict", "error")}
                                        if tl else None)})
            reviewed = sorted(r["_pen"] for r in rows if r["_pen"] is not None)
            neutral = reviewed[len(reviewed) // 2] if reviewed else 0.0  # yang dilewati Penelaah tidak boleh otomatis menang
            for r in rows:
                r["score"] = round(r.pop("_base") + (r["_pen"] if r["_pen"] is not None else neutral), 1)
                r.pop("_pen")
            rows.sort(key=lambda r: (r["excluded"] is not None, r["score"], 0 if r["asli"] else 1))
            best = next((r for r in rows if r["excluded"] is None), None)
            out[u["id"]] = {"best": (best["names"][0] if best else None), "rank": rows,
                            "note": ((tel.get("rank") or {}).get(u["id"]) or {}).get("note", "")}
        b._rank_cache = (key, out)
        return out


    def auto_pick(k, b, reason: str = "") -> int:
        """Pilih alternatif teratas per satuan. Satuan terkunci dan satuan tanpa alternatif lebih baik tetap asli.

        Kalau teks final sedang hasil edit manual, satuan yang diedit user dibiarkan; cuma satuan yang belum disentuh
        yang diganti alternatif terbaik.
        """
        r = rank(k, b)
        locked = set(b.locks)
        vm = {v["name"]: v for v in b.variants}
        edit_units = None
        if b.final_source == "edit":
            _, edit_units = k.final_text_units(b)
        picks, kept = {}, 0
        new_units = list(edit_units) if edit_units is not None else None
        for i, u in enumerate(b.units):
            if u["kind"] == "blank" or u["id"] in locked:
                continue
            best = (r.get(u["id"]) or {}).get("best")
            if new_units is not None:
                cur = (vm.get(b.picks.get(u["id"], "ASLI")) or vm["ASLI"])["units"][i]
                if new_units[i] != cur:  # diedit manual: jangan disentuh
                    kept += 1
                    if u["id"] in b.picks:
                        picks[u["id"]] = b.picks[u["id"]]
                    continue
                if best and best != "ASLI" and best in vm:
                    new_units[i] = vm[best]["units"][i]
                    picks[u["id"]] = best
                continue
            if best and best != "ASLI":
                picks[u["id"]] = best
        b.picks = picks
        if new_units is not None:
            segs = U.segment(b.final_text, b.profile["unit"])
            b.final_text = "".join(t + sg.sep for t, sg in zip(new_units, segs))
        elif b.final_source == "edit":
            b.final_source = "rakit"  # jumlah satuan edit tidak sejajar: kembali ke hasil rakit (bisa di-undo)
        else:
            b.final_source = "rakit"
        b.auto = {"t": now().strftime("%d-%m %H:%M"), "n": len(picks), "reason": reason, "kept_edits": kept}
        return len(picks)


    # ---------- ringkasan untuk widget ----------
    def variant_scores(k, b) -> dict:
        gi = gate_info(k, b)
        v = voice(k, b)
        sp = SP.get()
        lang = b.profile.get("language", "en")
        out = {}
        for x in b.variants:
            a = sp_analyze(k, b, x["text"], allow=refrain_phrases(b))
            fp = SU.fingerprint(x["text"], lang, a["points"])
            m = SU.match(fp, v)
            out[x["name"]] = {"slop_score": a["score"], "slop_points": a["points"], "slop_n": a["n"],
                              "items": [{"label": i["label"], "text": i["text"]} for i in a["items"]][:10],
                              "voice": m["score"], "voice_off": m["off"][:4]}
        return out


    def final_summary(k, b) -> dict:
        text, funits = k.final_text_units(b)
        if not text.strip():
            return {}
        gi = gate_info(k, b)
        v = voice(k, b)
        sp = SP.get()
        a = sp_analyze(k, b, text, allow=refrain_phrases(b))
        fp = SU.fingerprint(text, b.profile.get("language", "en"), a["points"])
        m = SU.match(fp, v)
        tel = b.telaah or {}
        reviewed, notes, units_notes, missing = 0, 0, [], []
        if funits is not None:
            for u, t in zip(b.units, funits):
                if u["kind"] == "blank" or not t.strip():
                    continue
                tl = (tel.get("texts") or {}).get(text_key(b, u["id"], t, review_sig(k, b), gi["context"]))
                if tl and not tl.get("error"):
                    reviewed += 1
                    n = len(tl.get("findings", [])) + len(tl.get("grammar", [])) + len(tl.get("meaning", []))
                    notes += n
                    if n:
                        units_notes.append({"unit": u["id"], "findings": tl.get("findings", []), "grammar": tl.get("grammar", []),
                                            "meaning": tl.get("meaning", []), "voice": tl.get("voice")})
                else:
                    missing.append(u["id"])
        return {"slop_score": a["score"], "slop_points": a["points"], "slop_n": a["n"],
                "items": [{"label": i["label"], "text": i["text"]} for i in a["items"]][:16],
                "voice": m["score"], "voice_off": m["off"], "fingerprint": {kk: fp.get(kk) for kk in SU.FEATURES if kk in fp},
                "reviewed": reviewed, "notes": notes, "units": units_notes, "missing": missing}


    def lang_of(b) -> str:
        """Bahasa efektif berkas: profil, kecuali teksnya jelas bahasa lain (deteksi kata fungsi)."""
        lang = b.profile.get("language", "en")
        try:
            from .puebi import detect_lang
            got = detect_lang(b.clean or "")
            if got and got != lang and len((b.clean or "").split()) >= 30:
                return got
        except Exception:  # noqa: BLE001
            pass
        return lang


    def sp_analyze(k, b, text: str, unit_level: bool = False, allow=None) -> dict:
        """Satpam dengan bahasa dan frasa ulang yang disengaja (refrain), kalau mesin Satpam mendukungnya."""
        import inspect
        sp = SP.get()
        kw = {}
        try:
            params = inspect.signature(sp.analyze).parameters
            if "lang" in params:
                kw["lang"] = lang_of(b)
            if "allow" in params and allow:
                kw["allow"] = list(allow)
        except (TypeError, ValueError):
            pass
        return sp.analyze(text, context_id(b), banned(k, b), unit_level=unit_level, **kw)


    def tren(k, b) -> dict:
        """Tren klise per bait/blok × versi (ASLI, tiap varian, FINAL): poin Satpam per blok."""
        units = b.units
        blocks = sorted({u["block"] for u in units if u["kind"] != "blank"})
        if not blocks:
            return {"blocks": [], "rows": []}
        blocks = blocks[:60]

        def per_block(texts: list[str]) -> list[int]:
            out = []
            for bl in blocks:
                t = "\n".join(x for u, x in zip(units, texts) if u["block"] == bl and u["kind"] != "blank" and x)
                out.append(int(sp_analyze(k, b, t, allow=refrain_phrases(b))["points"]) if t.strip() else 0)
            return out

        rows = []
        for v in b.variants[:13]:
            vu = v.get("units") or []
            if len(vu) != len(units):
                continue
            pts = per_block(vu)
            rows.append({"name": v["name"], "pts": pts, "total": sum(pts)})
        text, funits = k.final_text_units(b)
        if funits is not None and len(funits) == len(units):
            pts = per_block(funits)
            rows.append({"name": "FINAL", "pts": pts, "total": sum(pts)})
        labels = [("Bait " if b.profile.get("verse") or b.profile["unit"] == "line" else "Blok ") + str(x) for x in blocks]
        return {"blocks": labels, "rows": rows, "t": hhmm()}


    def snapshot(k, b) -> dict:
        s = b.settings
        sul = s.get("sulap") or {}
        v = voice(k, b)
        cid = context_id(b)
        sp = SP.get()
        pen = s.get("penelaah") or PEN_DEFAULT
        pstate = k.hub.statuses().get("penelaah", "belum")
        skills_used = RB.load_skills(pen.get("skills_dir") or "")[1] if pen.get("skills", "utuh") == "utuh" else []
        pack = [{"name": x["name"], "role": x.get("role"), "kb": round(x.get("chars", 0) / 1024)} for x in RB.skill_pack()]
        try:
            units = rank(k, b)
        except Exception as ex:  # noqa
            k.log("warn", f"Peringkat gagal dihitung: {ex!r}"[:200])
            units = {}
        try:
            vs = variant_scores(k, b) if b.variants else {}
            fin = final_summary(k, b)
        except Exception as ex:  # noqa
            k.log("warn", f"Ringkasan Satpam gagal: {ex!r}"[:200])
            vs, fin = {}, {}
        todo_v = telaah_todo(k, b, "varian") if b.variants and len(b.variants) > 1 else []
        todo_f = telaah_todo(k, b, "final") if b.units else []
        return {
            "on": {"satpam": bool(sul.get("satpam", True)), "telaah": bool(sul.get("telaah", True)),
                   "auto_pick": bool(sul.get("auto_pick", True))},
            "context": {"id": cid, "label": SP.CONTEXTS[cid]["label"], "note": SP.CONTEXTS[cid]["note"],
                        "auto": (s.get("satpam") or {}).get("context", "otomatis") == "otomatis"},
            "contexts": SP.contexts_public(),
            "satpam": {**sp.info(), "mode": (s.get("satpam") or {}).get("mode", "saring")},
            "suara": SU.public(v),
            "suara_setting": (s.get("suara") or {}).get("id", "otomatis"),
            "voices": SU.options(k.voices),
            "features": {kk: vv[0] for kk, vv in SU.FEATURES.items()},
            "penelaah": {"on": bool(sul.get("telaah", True)), "state": pstate, "model": pen.get("model"),
                         "load": pen.get("load"), "skills": pen.get("skills"), "skills_dir": pen.get("skills_dir"),
                         "skills_used": skills_used, "cpu_only": bool(k.env.get("cpu_only")),
                         "stats": (b.telaah or {}).get("stats"), "todo_varian": len(todo_v), "todo_final": len(todo_f),
                         "thinking": pen.get("thinking", "dipandu"), "pack": pack,
                         "cache": k.hub.statuses().get("penelaah_cache"), "drafter": k.hub.statuses().get("drafter"),
                         "drafter_note": getattr(k.hub, "drafter_note", "")},
            "aturan": {"rules": list(k.aturan.rules), "never": list(k.aturan.never)},
            "tren": b.tren or None,
            "lang": lang_of(b),
            "memori": {"n": len(k.memori.items), "recent": k.memori.recent(5)},
            "rubrik": [{"id": r[0], "name": r[1], "level": r[2]} for r in RB.RULES]
                      + [{"id": kk, "name": vv, "level": "P1"} for kk, vv in RB.custom_rule_names(k.aturan.rules).items()],
            "units": units,
            "variants": vs,
            "final": fin,
            "auto": b.auto or {},
            "saran": b.saran or {},
            "words": len(words(b.clean)) if b.clean else 0,
        }


    def build_guide(k, v: dict, seed: int = 7) -> dict:
        """Voice Guide dari contoh tulisan (tahapan voice-extractor), disusun Penelaah lalu divalidasi terhadap contohnya."""
        fp = v.get("fingerprint") or {}
        measured = "; ".join(f"{SU.FEATURES[key][0]}: {fp.get(key)}" for key in SU.FEATURES if fp.get(key) is not None)
        msgs = RB.suara_messages(system=system_for(k, k.b), samples=v.get("samples", ""), measured=measured,
                                 lang=v.get("lang", "en"))
        data, _ = _chat_json(k, msgs, seed, k.b, "SUARA")
        if not data:
            raise ValueError("Penelaah tidak mengembalikan Voice Guide yang bisa dibaca.")
        low = (v.get("samples") or "").lower()
        sig = [s for s in (data.get("signature_phrases") or []) if isinstance(s, str) and s.strip() and s.lower() in low][:12]
        lst = lambda key, n: [str(x)[:160] for x in (data.get(key) or []) if str(x).strip()][:n]  # noqa: E731
        g = {"role": str(data.get("role", ""))[:80], "energy": str(data.get("energy", ""))[:80], "traits": lst("traits", 6),
             "do": lst("do", 6), "dont": lst("dont", 6), "signature_phrases": sig, "never": lst("never", 30),
             "model": (k.b.settings.get("penelaah") or {}).get("model"), "t": now().strftime("%d-%m %H:%M")}
        test = data.get("test") or {}
        v["guide"] = g
        v["validation"] = {"topic": str(test.get("topic", ""))[:80], "a": str(test.get("a", ""))[:500],
                           "b": str(test.get("b", ""))[:500], "ok": None}
        extra = [w for w in g["never"] if w.lower() not in low]
        v["never_auto"] = list(dict.fromkeys((v.get("never_auto") or []) + extra))[:200]
        if sig:
            v["signature"] = list(dict.fromkeys(sig + (v.get("signature") or [])))[:16]
        v["desc"] = SU.describe(v)
        k.voices.save(v)
        k.log("ok", f"Voice Guide '{v.get('label')}' tersusun. Cek tes A/B di Disposisi › Suara.")
        return g

    ''')
    return (f_meja_sulap_py,)


@app.cell(hide_code=True)
def meja_textcheck_py(tulis):
    # meja/textcheck.py
    f_meja_textcheck_py = tulis("meja/textcheck.py", r'''
    """Cek varian dan teks final terhadap naskah asli (lapis 4-6 Pemeriksa Fakta + kebersihan)."""
    from __future__ import annotations

    import difflib

    from . import facts as F
    from . import units as U
    from .util import count_dashes, count_non_ascii, words


    def change_pct(a: str, b: str) -> float:
        if a == b:
            return 0.0
        wa, wb = a.split(), b.split()
        if not wa and not wb:
            return 0.0
        return round(100.0 * (1.0 - difflib.SequenceMatcher(None, wa, wb, autojunk=False).ratio()), 1)


    def run_problems(orig: str, new: str, run_facts: list[dict], profile: dict, lang: str) -> list[str]:
        """Alasan menolak keluaran model untuk satu deret satuan (dipakai Humas per bait/kalimat)."""
        why = []
        lost = [f["text"] for f in run_facts if not F.fact_present(f, orig, new)]
        if lost:
            why.append("hilang: " + ", ".join(lost))
        if profile["style"].get("no_em_dash") and count_dashes(new) > count_dashes(orig):
            why.append("ada em/en dash")
        if profile["style"].get("ascii_only") and count_non_ascii(new) > count_non_ascii(orig):
            why.append("ada karakter non-ASCII")
        nf = F.new_facts(orig, new, lang)
        if nf:
            why.append("angka/nama baru: " + ", ".join(nf[:5]))
        if not new.strip():
            why.append("keluaran kosong")
        return why


    def assess(orig_units: list[str], new_units: list[str], seps: list[str], unit_ids: list[str],
               facts: list[dict], profile: dict, locked: set[str]) -> dict:
        orig = U.join(orig_units, seps)
        new = U.join(new_units, seps)
        lang = profile.get("language", "en")
        issues: list[str] = []
        fmap = {f["id"]: F.fact_present(f, orig, new) for f in facts}
        lost = [f["text"] for f in facts if not fmap[f["id"]]]
        if lost:
            issues.append("fakta hilang: " + ", ".join(lost))
        nf = F.new_facts(orig, new, lang)
        if nf:
            issues.append("angka/nama baru: " + ", ".join(nf[:8]))
        if profile["style"].get("no_em_dash") and count_dashes(new):
            issues.append(f"ada em/en dash ({count_dashes(new)})")
        if profile["style"].get("ascii_only") and count_non_ascii(new):
            issues.append(f"ada karakter non-ASCII ({count_non_ascii(new)})")
        changed_locked = [uid for uid, a, b in zip(unit_ids, orig_units, new_units) if uid in locked and a != b]
        if changed_locked:
            issues.append("satuan terkunci berubah: " + ", ".join(changed_locked))
        if len(new_units) != len(orig_units):
            issues.append(f"jumlah satuan {len(new_units)} != {len(orig_units)}")
        c = U.counts(new, [], profile)
        for lim in U.limits(c, profile):
            if not lim["ok"]:
                issues.append(f"{lim['label']} {lim['value']} < {lim['min']}" if lim.get("min") is not None
                              else f"{lim['label']} {lim['value']} > {lim['max']}")
        pct = {uid: change_pct(a, b) for uid, a, b in zip(unit_ids, orig_units, new_units) if a != b}
        return {"ok": not issues, "issues": issues, "facts": fmap, "change_pct": pct}


    def final_checks(orig_units: list[str], final_text: str, final_units: list[str] | None, seps: list[str],
                     unit_ids: list[str], facts: list[dict], profile: dict, locked: set[str]) -> list[dict]:
        """Cek langsung untuk editor final di Meja Korektor."""
        orig = U.join(orig_units, seps)
        lang = profile.get("language", "en")
        out = []
        c = U.counts(final_text, [], profile)
        for lim in U.limits(c, profile):
            out.append({"id": lim["key"], "label": f"{lim['label']} {lim['value']}" + (f" (min {lim['min']})" if lim.get("min") is not None
                                                                                      else f"/{lim['max']}"), "ok": lim["ok"], "detail": ""})
        lost = [f["text"] for f in facts if not F.fact_present(f, orig, final_text)]
        out.append({"id": "facts", "label": f"Fakta utuh {len(facts) - len(lost)}/{len(facts)}", "ok": not lost,
                    "detail": ", ".join(lost)})
        nf = F.new_facts(orig, final_text, lang)
        out.append({"id": "new_facts", "label": "Tidak ada angka/nama baru", "ok": not nf, "detail": ", ".join(nf)})
        if profile["style"].get("no_em_dash"):
            d = count_dashes(final_text)
            out.append({"id": "dash", "label": "Tanpa em/en dash", "ok": d == 0, "detail": f"{d} ditemukan" if d else ""})
        if profile["style"].get("ascii_only"):
            n = count_non_ascii(final_text)
            out.append({"id": "ascii", "label": "Hanya ASCII", "ok": n == 0, "detail": f"{n} karakter" if n else ""})
        if final_units is not None and len(final_units) == len(orig_units):
            ch = [uid for uid, a, b in zip(unit_ids, orig_units, final_units) if uid in locked and a != b]
            out.append({"id": "locks", "label": "Satuan terkunci utuh", "ok": not ch, "detail": ", ".join(ch)})
        else:
            n_new = sum(1 for sg in U.segment(final_text, profile["unit"]) if sg.text.strip())
            n_old = sum(1 for t in orig_units if t.strip())
            out.append({"id": "units", "label": f"Jumlah satuan isi {n_new}/{n_old}",
                        "ok": n_new == n_old or not profile["limits"].get("keep_unit_count"), "detail": "" if n_new == n_old else "jumlah satuan berubah"})
            if locked:
                out.append({"id": "locks", "label": "Satuan terkunci tidak bisa dicek (jumlah satuan berubah)", "ok": False,
                            "detail": ", ".join(sorted(locked))[:120]})
        out.append({"id": "empty", "label": "Teks tidak kosong", "ok": bool(words(final_text)), "detail": ""})
        return out

    ''')
    return (f_meja_textcheck_py,)


@app.cell(hide_code=True)
def meja_units_py(tulis):
    # meja/units.py
    f_meja_units_py = tulis("meja/units.py", r'''
    """Memecah naskah jadi satuan olah (baris, kalimat, paragraf) yang bisa dirakit ulang persis.

    Setiap satuan menyimpan `text` dan `sep` (spasi/baris baru sesudahnya), jadi
    "".join(text + sep) selalu sama dengan naskah aslinya.
    """
    from __future__ import annotations

    import re
    from dataclasses import dataclass

    from .util import count_dashes, count_non_ascii, occurrences, words

    ABBR = {
        "mr", "mrs", "ms", "dr", "prof", "st", "no", "vs", "etc", "e.g", "i.e", "jr", "sr", "fig", "vol", "p", "pp",
        "jl", "dll", "dsb", "tgl", "bpk", "sdr", "yth", "hlm", "kec", "kab", "ds", "a.n", "u.p", "dkk", "ybs",
    }
    _SENT_RE = re.compile(r"([.!?…]+[\"'”’)\]]*)([ \t]*\n[\s]*|[ \t]+)|(\n+)")


    @dataclass
    class Seg:
        text: str
        sep: str
        kind: str
        block: int


    def normalize_newlines(raw: str) -> str:
        t = (raw or "").replace("\r\n", "\n").replace("\r", "\n")
        t = "\n".join(line.rstrip() for line in t.split("\n"))
        return t.strip("\n")


    def _is_abbrev(before: str) -> bool:
        m = re.search(r"([A-Za-z][A-Za-z.]*)$", before)
        if not m:
            return False
        w = m.group(1).lower().rstrip(".")
        return w in ABBR or len(w) == 1


    def split_sentences(text: str) -> list[tuple[str, str]]:
        """Kalimat + pemisah. Baris baru tunggal juga dianggap batas (caption, daftar, tagar)."""
        out: list[tuple[str, str]] = []
        start = 0
        for m in _SENT_RE.finditer(text):
            if m.group(3) is not None:  # baris baru tanpa tanda baca
                piece, sep, nxt = text[start:m.start()], m.group(3), m.end()
            else:
                ws = m.group(2)
                after = text[m.end():m.end() + 2]
                if "\n" not in ws:
                    if not re.match(r"[\"'“‘(\[]?[A-Z0-9À-ÝĀ-Ž#@]", after):
                        continue
                    if m.group(1).startswith(".") and _is_abbrev(text[start:m.start()]):
                        continue
                piece, sep, nxt = text[start:m.end(1)], ws, m.end()
            if piece.strip():
                out.append((piece, sep))
            elif out:
                out[-1] = (out[-1][0], out[-1][1] + piece + sep)
            start = nxt
        tail = text[start:]
        if tail.strip():
            stripped = tail.rstrip()
            out.append((stripped, tail[len(stripped):]))
        elif out:
            out[-1] = (out[-1][0], out[-1][1] + tail)
        return out


    def segment(text: str, unit: str) -> list[Seg]:
        segs: list[Seg] = []
        if not text:
            return segs
        if unit == "line":
            block = 1
            lines = text.split("\n")
            prev_blank = False
            for i, line in enumerate(lines):
                sep = "\n" if i < len(lines) - 1 else ""
                if line.strip():
                    if prev_blank:
                        block += 1
                    segs.append(Seg(line, sep, "line", block))
                    prev_blank = False
                else:
                    segs.append(Seg("", sep, "blank", block))
                    prev_blank = True
            return segs
        # paragraf dipisah baris kosong
        parts = re.split(r"(\n[ \t]*\n\s*)", text)
        block = 0
        for j in range(0, len(parts), 2):
            par = parts[j]
            gap = parts[j + 1] if j + 1 < len(parts) else ""
            if not par.strip():
                if segs:
                    segs[-1].sep += par + gap
                continue
            block += 1
            if unit == "paragraph":
                segs.append(Seg(par, gap, "paragraph", block))
            else:
                sents = split_sentences(par)
                for k, (s, sp) in enumerate(sents):
                    segs.append(Seg(s, sp + (gap if k == len(sents) - 1 else ""), "sentence", block))
        return segs


    def join(texts: list[str], seps: list[str]) -> str:
        return "".join(t + s for t, s in zip(texts, seps))


    def resplit_run(text: str, unit: str, n: int) -> list[str] | None:
        """Pecah keluaran model untuk satu deret satuan. None kalau jumlahnya tidak cocok."""
        text = (text or "").strip()
        if unit == "line":
            parts = [ln.strip() for ln in text.split("\n") if ln.strip()]
        elif unit == "paragraph":
            parts = [p.strip() for p in re.split(r"\n\s*\n", text) if p.strip()]
        else:
            parts = [s.strip() for s, _ in split_sentences(text) if s.strip()]
        return parts if len(parts) == n else None


    def run_text(texts: list[str], seps: list[str], unit: str) -> str:
        if unit == "line":
            return "\n".join(t.strip() for t in texts)
        if unit == "paragraph":
            return "\n\n".join(t.strip() for t in texts)
        return "".join(t + (s if i < len(texts) - 1 else "") for i, (t, s) in enumerate(zip(texts, seps))).strip()


    # ---------------- suku kata dan rima ----------------

    def syllables_word(w: str, lang: str = "en") -> int:
        w = re.sub(r"[^a-z]", "", w.lower())
        if not w:
            return 0
        if lang == "id":
            return max(1, len(re.findall(r"ai|au|oi|ei|[aiueo]", w)))
        if len(w) <= 3:
            return 1
        w = re.sub(r"(?:[^laeiouy]es|[^laeiouy]ed|[^laeiouy]e)$", lambda m: m.group(0)[0], w)
        w = re.sub(r"^y", "", w)
        n = len(re.findall(r"[aeiouy]+", w))
        if re.search(r"[^aeiouy]le$", w):
            n += 1
        return max(1, n)


    def syllables(text: str, lang: str = "en") -> int:
        return sum(syllables_word(w, lang) for w in words(text))


    def rhyme_key(line: str) -> str:
        ws = re.findall(r"[A-Za-z]+", line)
        if not ws:
            return ""
        w = ws[-1].lower()
        m = re.search(r"[aeiouy]+[^aeiouy]*$", w)
        key = m.group(0) if m else w
        if key == "e" and len(w) > 2:
            m2 = re.search(r"[aeiouy]+[^aeiouy]+e$", w)
            key = m2.group(0) if m2 else w[-3:]
        return key


    def rhyme_tags(keys: list[str]) -> list[str]:
        counts: dict[str, int] = {}
        for k in keys:
            if k:
                counts[k] = counts.get(k, 0) + 1
        letters: dict[str, str] = {}
        out = []
        for k in keys:
            if not k or counts.get(k, 0) < 2:
                out.append("-" if k else "")
                continue
            if k not in letters:
                n = len(letters)
                letters[k] = chr(ord("A") + n % 26) + ("" if n < 26 else str(n // 26))
            out.append(letters[k])
        return out


    # ---------------- frasa miring ----------------

    _MARK_RE = re.compile(r"(?<![\w*])\*(?!\*)([^*\n]+?)\*(?![\w*])|(?<![\w_])_(?!_)([^_\n]+?)_(?![\w_])")


    def strip_italic_markers(text: str) -> tuple[str, list[str]]:
        """`*frasa*` atau `_frasa_` → teks tanpa penanda + daftar frasa miring."""
        phrases: list[str] = []

        def rep(m):
            p = m.group(1) or m.group(2)
            phrases.append(p.strip())
            return p

        out = _MARK_RE.sub(rep, text)
        seen, uniq = set(), []
        for p in phrases:
            if p and p.lower() not in seen:
                seen.add(p.lower())
                uniq.append(p)
        return out, uniq


    def italic_spans(text: str, phrases: list[str]) -> list[list[int]]:
        spans = []
        for p in sorted(phrases, key=len, reverse=True):
            for a, b in occurrences(p, text):
                if not any(a < y and x < b for x, y in spans):
                    spans.append([a, b])
        return sorted(spans)


    # ---------------- ringkasan ----------------

    def build_units(text: str, profile: dict, italic: list[str]) -> tuple[list[dict], list[str]]:
        segs = segment(text, profile["unit"])
        lang = profile.get("language", "en")
        verse = profile.get("verse")
        keys = [rhyme_key(s.text) if verse and s.kind == "line" else "" for s in segs]
        tags = rhyme_tags(keys) if verse else [""] * len(segs)
        units = []
        for i, s in enumerate(segs):
            u = {
                "id": f"u{i + 1}", "i": i + 1, "text": s.text, "block": s.block, "kind": s.kind,
                "words": len(words(s.text)), "chars": len(s.text),
                "italic": italic_spans(s.text, italic), "facts": [],
            }
            if verse:
                u["syllables"] = syllables(s.text, lang) if s.text else 0
                u["rhyme"] = keys[i]
                u["rhyme_tag"] = tags[i]
            units.append(u)
        return units, [s.sep for s in segs]


    def strip_roles(text: str, role_texts: list[str]) -> str:
        """Buang satuan berperan (judul/referensi/catatan) dari hitungan batas: kemunculan pertama tiap teks."""
        for rt in role_texts or []:
            if not rt or not rt.strip():
                continue
            lines = text.split("\n")
            if rt in lines:
                i = lines.index(rt)
                del lines[i]
                if 0 < i < len(lines) and not lines[i - 1].strip() and not lines[i].strip():
                    del lines[i]
                text = "\n".join(lines)
            else:
                text = text.replace(rt, "", 1)
        return re.sub(r"\A\s*\n+", "", text)


    def counts(text: str, units: list[dict], profile: dict) -> dict:
        if profile.get("_role_texts"):
            text = strip_roles(text, profile["_role_texts"])
        lines = text.split("\n") if text else []
        text_lines = [ln for ln in lines if ln.strip()]
        sentences = sum(1 for _ in split_sentences(text)) if text else 0
        return {
            "lines": len(lines), "text_lines": len(text_lines),
            "blocks": max((u["block"] for u in units), default=0),
            "words": len(words(text)), "chars": len(text), "sentences": sentences,
            "non_ascii": count_non_ascii(text), "dashes": count_dashes(text), "units": len(units),
        }


    def limits(c: dict, profile: dict, pages: int | None = None) -> list[dict]:
        L = profile["limits"]
        out = []
        if L.get("max_lines"):
            v = c["lines"] if L.get("count_blank") else c["text_lines"]
            out.append({"key": "max_lines", "label": "Baris" + (" (termasuk spasi bait)" if L.get("count_blank") else ""),
                        "value": v, "max": L["max_lines"], "ok": v <= L["max_lines"]})
        for key, label, field in (("max_words", "Kata", "words"), ("max_chars", "Karakter", "chars"),
                                  ("max_sentences", "Kalimat", "sentences")):
            if L.get(key):
                out.append({"key": key, "label": label, "value": c[field], "max": L[key], "ok": c[field] <= L[key]})
        if L.get("max_pages") and pages is not None:
            out.append({"key": "max_pages", "label": "Halaman", "value": pages, "max": L["max_pages"], "ok": pages <= L["max_pages"]})
        for key, label, field in (("min_lines", "Baris", "text_lines"), ("min_words", "Kata", "words"), ("min_chars", "Karakter", "chars")):
            if L.get(key):
                out.append({"key": key, "label": label, "value": c[field], "min": L[key], "max": None, "ok": c[field] >= L[key]})
        return out

    ''')
    return (f_meja_units_py,)


@app.cell(hide_code=True)
def meja_util_py(tulis):
    # meja/util.py
    f_meja_util_py = tulis("meja/util.py", r'''
    """Alat kecil yang dipakai semua stasiun."""
    from __future__ import annotations

    import base64
    import copy
    import datetime as _dt
    import hashlib
    import re
    import unicodedata

    try:
        from zoneinfo import ZoneInfo
        WIB = ZoneInfo("Asia/Jakarta")
    except Exception:  # tzdata tidak ada
        WIB = _dt.timezone(_dt.timedelta(hours=7), "WIB")

    WORD_RE = re.compile(r"[^\W\d_](?:[^\W\d_]|['’-](?=[^\W\d_]))*", re.UNICODE)
    DASH_RE = re.compile(r"[‒–—―⸺⸻]|(?<=\s)--(?=\s)")


    class UserError(Exception):
        """Kesalahan yang pesannya boleh langsung ditunjukkan ke user."""


    def now() -> _dt.datetime:
        return _dt.datetime.now(WIB)


    def now_iso() -> str:
        return now().isoformat(timespec="seconds")


    def hhmmss() -> str:
        return now().strftime("%H:%M:%S")


    def hhmm() -> str:
        return now().strftime("%H:%M")


    def short_hash(text: str, n: int = 8) -> str:
        return hashlib.sha256(text.encode("utf-8")).hexdigest()[:n]


    def full_hash(text: str) -> str:
        return hashlib.sha256(text.encode("utf-8")).hexdigest()


    def b64e(data: bytes) -> str:
        return base64.b64encode(data).decode("ascii")


    def b64d(s: str) -> bytes:
        if "," in s[:100] and s.lstrip().startswith("data:"):
            s = s.split(",", 1)[1]
        return base64.b64decode(s)


    def deep_merge(base: dict, patch: dict) -> dict:
        """Gabung dalam: dict digabung, nilai lain (termasuk list) diganti utuh."""
        out = copy.deepcopy(base)
        for k, v in (patch or {}).items():
            if isinstance(v, dict) and isinstance(out.get(k), dict):
                out[k] = deep_merge(out[k], v)
            else:
                out[k] = copy.deepcopy(v)
        return out


    def slug(title: str, fallback: str = "Naskah") -> str:
        t = unicodedata.normalize("NFKD", title or "").encode("ascii", "ignore").decode()
        t = re.sub(r"[^A-Za-z0-9]+", "_", t).strip("_")
        return t[:60] or fallback


    def words(text: str) -> list[str]:
        return WORD_RE.findall(text or "")


    def count_non_ascii(text: str) -> int:
        return sum(1 for c in text if ord(c) > 127)


    def count_dashes(text: str) -> int:
        return len(DASH_RE.findall(text or ""))


    def char_name(ch: str) -> str:
        try:
            return unicodedata.name(ch)
        except ValueError:
            return {"\u200b": "ZERO WIDTH SPACE"}.get(ch, "TANPA NAMA")


    def fmt_secs(s: float | None) -> str:
        if s is None:
            return "-"
        s = int(s)
        if s < 60:
            return f"{s}d"
        m, s = divmod(s, 60)
        if m < 60:
            return f"{m}m{s:02d}d"
        h, m = divmod(m, 60)
        return f"{h}j{m:02d}m"


    def occurrences(needle: str, hay: str, *, ci: bool = True) -> list[tuple[int, int]]:
        """Posisi kemunculan `needle` di `hay` yang tidak menempel ke huruf/angka lain."""
        if not needle:
            return []
        pat = r"(?<!\w)" + re.escape(needle) + r"(?!\w)"
        return [(m.start(), m.end()) for m in re.finditer(pat, hay, re.I if ci else 0)]

    ''')
    return (f_meja_util_py,)


@app.cell(hide_code=True)
def meja_widget_py(tulis):
    # meja/widget.py
    f_meja_widget_py = tulis("meja/widget.py", r'''
    """Widget anywidget MEJA REDAKSI: satu-satunya sumber kebenaran antara UI dan mesin."""
    from __future__ import annotations

    import copy
    import os
    from pathlib import Path

    import anywidget
    import traitlets

    from .kantor import KEYS, Kantor

    STATIC = Path(__file__).resolve().parent.parent / "static"


    def _asset(name: str) -> Path:
        p = STATIC / name
        if not p.exists():
            raise FileNotFoundError(f"{p} tidak ada. Folder static/ harus ikut bersama paket meja/.")
        return p


    class MejaRedaksi(anywidget.AnyWidget):
        _esm = _asset("widget.js")
        _css = _asset("widget.css")

        # milik mesin
        app = traitlets.Dict({}).tag(sync=True)
        env = traitlets.Dict({}).tag(sync=True)
        profiles = traitlets.List([]).tag(sync=True)
        berkas = traitlets.Dict({}).tag(sync=True)
        naskah = traitlets.Dict({}).tag(sync=True)
        facts = traitlets.List([]).tag(sync=True)
        locks = traitlets.List([]).tag(sync=True)
        kamus = traitlets.List([]).tag(sync=True)
        settings = traitlets.Dict({}).tag(sync=True)
        estimate = traitlets.Dict({}).tag(sync=True)
        status = traitlets.Dict({}).tag(sync=True)
        jobs = traitlets.List([]).tag(sync=True)
        log = traitlets.List([]).tag(sync=True)
        variants = traitlets.List([]).tag(sync=True)
        picks = traitlets.Dict({}).tag(sync=True)
        final = traitlets.Dict({}).tag(sync=True)
        history = traitlets.List([]).tag(sync=True)
        notes = traitlets.Dict({}).tag(sync=True)
        proof = traitlets.List([]).tag(sync=True)
        rapat = traitlets.Dict({}).tag(sync=True)
        segel = traitlets.Dict({}).tag(sync=True)
        audit = traitlets.List([]).tag(sync=True)
        cetak = traitlets.Dict({}).tag(sync=True)
        rules_proposal = traitlets.Dict(None, allow_none=True).tag(sync=True)
        compare = traitlets.Dict({}).tag(sync=True)
        sulap = traitlets.Dict({}).tag(sync=True)
        meja = traitlets.Dict({}).tag(sync=True)
        ack = traitlets.Dict({}).tag(sync=True)
        # milik widget
        command = traitlets.Dict({}).tag(sync=True)
        prefs = traitlets.Dict({"theme": "dark", "font_scale": 1.0, "sound": True, "notify": False,
                                "presentation": False, "tab": "loket"}).tag(sync=True)

        def __init__(self, hub=None, home=None, check_env: bool = True, **kw):
            super().__init__(**kw)
            if hub is None and os.environ.get("MEJA_STUB"):
                from .hub import StubHub
                hub = StubHub()
            self.kantor = Kantor(hub=hub, home=home, push=self._push_keys, check_env=check_env)
            if os.environ.get("MEJA_STUB") and os.environ.get("MEJA_STUB_GPU"):
                self.kantor.env["cpu_only"] = False  # khusus uji: pura-pura ada GPU supaya alur Humas/Penelaah tiruan jalan
            self._apply(self.kantor.flush(KEYS))
            if not os.environ.get("MEJA_NO_GUARD"):
                self.kantor.start_guard()   # simpan meja + teruskan lini rakit kalau layar tertutup

        def _apply(self, updates: dict):
            # selalu salinan baru: state mesin sering diubah di tempat, dan traitlets diam kalau nilai lama == baru
            with self.hold_sync():
                for k, v in updates.items():
                    if v is None and k != "rules_proposal":
                        v = {} if isinstance(getattr(self, k), dict) else []
                    setattr(self, k, copy.deepcopy(v))

        def _push_keys(self, keys):
            self._apply(self.kantor.flush(keys))

        @traitlets.observe("command")
        def _on_command(self, change):
            cmd = change.get("new") or {}
            if not cmd.get("op"):
                return
            with self.kantor.lock:   # penjaga di belakang memakai kunci yang sama
                try:
                    ack = self.kantor.handle(cmd)
                except Exception as ex:  # noqa: BLE001  handle() sudah menangkap error op; ini jaring terakhir
                    ack = {"id": cmd.get("id"), "ok": False, "op": cmd.get("op"), "msg": f"Kesalahan mesin: {type(ex).__name__}: {ex}"[:300]}
                try:
                    self._apply(self.kantor.flush())
                except Exception as ex:  # noqa: BLE001  satu snapshot rusak tidak boleh membuat widget menunggu selamanya
                    self.kantor.dirty.clear()
                    ack = {**ack, "ok": False, "msg": (ack.get("msg") or "") + f" · Tampilan gagal diperbarui: {type(ex).__name__}"}
                finally:
                    self.ack = ack

        def send_command(self, op: str, **args) -> dict:
            """Untuk dipakai dari sel Python (tes, otomasi)."""
            n = int((self.command or {}).get("id") or 0) + 1
            self.command = {"op": op, "id": n, "args": args}
            return self.ack

    ''')
    return (f_meja_widget_py,)


